/**
 * Editorial SEO content for individual developer tool pages.
 *
 * Structure: <h2> headings + <p> paragraphs + <h3> for FAQ questions.
 * Each tool's content follows 5 sections:
 *   1. What is [Tool] — 2-3 sentences on real behavior
 *   2. How to Use [Tool] — numbered steps against actual UI
 *   3. Why Use [Tool] — genuine use cases
 *   4. Privacy & Security — identical across all tools
 *   5. FAQ — 3-5 questions as <h3>
 *
 * Target: 500-1000 words per tool.
 */

export interface SeoContentBlock {
  type: "paragraph" | "list";
  text?: string;
  items?: string[];
}

export interface SeoSection {
  heading: string;
  subHeading?: string;
  paragraphs?: string[];
  content?: SeoContentBlock[];
}

export interface ToolSeo {
  sections: SeoSection[];
}

/**
 * Privacy & Security boilerplate — byte-identical across all 316 tools.
 * Inserted as the 4th section in every tool's content.
 */
export const PRIVACY_SECURITY_BLOCK: SeoSection = {
  heading: "Privacy & Security",
  content: [
    {
      type: "paragraph",
      text: "This tool runs entirely in your browser — no data ever leaves your device. There is no server round-trip, no upload, no logging, and no account required. Your input is processed locally using client-side JavaScript and is never stored, transmitted, or accessible to anyone else. When you close the tab, everything disappears.",
    },
  ],
};

/**
 * SEO content registry — slug → ToolSeo.
 * Populated by scripts/developers-json-to-seo.ts.
 */
const seoRegistry = new Map<string, ToolSeo>();

export function registerToolSeo(slug: string, seo: ToolSeo) {
  seoRegistry.set(slug, seo);
}

export function getToolSeo(slug: string): ToolSeo | undefined {
  return seoRegistry.get(slug);
}

export function hasToolSeo(slug: string): boolean {
  return seoRegistry.has(slug);
}



const css_formatterSeo: ToolSeo = {
  sections: [
    { heading: "What is Css Formatter", content: [
      { type: "paragraph", text: "<p>The CSS Formatter is a client-side code beautifier that uses Prettier's PostCSS plugin to parse and reformat CSS according to standard style conventions. It automatically inserts consistent indentation, line breaks, and spacing — transforming minified or poorly formatted CSS into a readable, standardized layout. The formatter respects CSS syntax rules, preserving selectors, properties, values, and at-rules while reorganizing whitespace for maximum readability. Unlike simple find-and-replace formatting tools, this formatter uses a full CSS parser that understands the CSS grammar, ensuring that reformatting never accidentally breaks syntax or changes the visual output of your stylesheets.</p>" },
    ]},
    { heading: "How to Use Css Formatter", content: [
      { type: "list", items: [
        "<p><strong>Step 1:</strong> Paste your CSS code into the input textarea on the left side of the tool. The formatter accepts any valid CSS — including modern syntax like nesting, custom properties, and @layer rules.</p>",
        "<p><strong>Step 2:</strong> Click the Transform button to trigger formatting. Prettier's PostCSS parser processes the entire input entirely in your browser using WebAssembly — no data leaves your device and no server call is made.</p>",
        "<p><strong>Step 3:</strong> The reformatted CSS appears in the output panel with consistent indentation (two spaces by default), logical line breaks after each declaration, and standardized spacing around colons and commas.</p>",
        "<p><strong>Step 4:</strong> Copy the reformatted code using the built-in copy button in the output panel, or select it manually. The output is valid CSS that can be pasted directly into any stylesheet or build pipeline.</p>",
      ]},
    ]},
    { heading: "Why Use Css Formatter", content: [
      { type: "paragraph", text: "<p>Consistent CSS formatting is essential for team collaboration, code reviews, and long-term maintainability. Unformatted CSS — especially CSS generated by preprocessors, build tools, minifiers, or third-party libraries — is difficult to read and debug. When multiple developers work on the same stylesheet without a shared formatting standard, diffs become noisy and code reviews focus on whitespace instead of logic. The CSS Formatter standardizes style across your entire codebase in a single action, eliminating formatting debates and making every file equally navigable regardless of who wrote it.</p>" },
    ]},
    { heading: "Privacy & Security", content: [
      { type: "paragraph", text: "This tool runs entirely in your browser — no data ever leaves your device. There is no server round-trip, no upload, no logging, and no account required. Your input is processed locally using client-side JavaScript and is never stored, transmitted, or accessible to anyone else. When you close the tab, everything disappears." },
    ]},
    { heading: "Frequently Asked Questions", content: [
      { type: "paragraph", text: "<h3>Does the formatter change my CSS logic or visual output?</h3><p>No. The formatter only adjusts whitespace, indentation, and line breaks. It does not modify property values, reorder declarations, merge selectors, or change any functional behavior of your CSS. The reformatted output produces identical visual results in a browser.</p>" },
      { type: "paragraph", text: "<h3>What CSS features and syntax are supported?</h3><p>The formatter supports all standard CSS including nested selectors (the CSS Nesting specification), at-rules like @media, @keyframes, @supports, and @layer, custom properties (--variable), calc() and clamp() functions, and modern selectors like :has() and :is(). It uses Prettier's full PostCSS plugin for parsing.</p>" },
      { type: "paragraph", text: "<h3>Is there a maximum input size?</h3><p>The tool works entirely in your browser's memory. Extremely large files (over several megabytes) may cause brief pauses depending on your device's processing power, but there is no hard limit. The formatter processes input synchronously in the main thread.</p>" },
      { type: "paragraph", text: "<h3>Can I use this for SCSS, LESS, or other preprocessors?</h3><p>This tool uses the PostCSS parser which handles standard CSS syntax. For SCSS or LESS files that contain preprocessor-specific syntax like variables ($var), mixins, or @extend directives, you would need a dedicated Sass or Less formatter, as those preprocessors have different parsing rules.</p>" },
      { type: "paragraph", text: "<h3>How does this compare to editor auto-formatting?</h3><p>The output matches what Prettier would produce in VS Code or other editors with the Prettier extension installed. This tool is useful when you don't have an editor configured, want to format CSS from a code snippet, or need to batch-format code pasted from documentation or Stack Overflow.</p>" },
    ]},
  ],
};
registerToolSeo("css-formatter", css_formatterSeo);

