const box_shadow_generatorSeo: ToolSeo = {
  sections: [
    { heading: "What is Box Shadow Generator", content: [
      { type: "paragraph", text: "<p>The Box Shadow Generator is an interactive visual tool that builds CSS box-shadow declarations through real-time parameter adjustment. It controls six properties: horizontal offset (X), vertical offset (Y), blur radius, spread radius, shadow color (via a native color picker), and an optional inset toggle. The tool outputs the exact CSS box-shadow declaration and shows a live preview of the shadow applied to a rounded white sample element against the page background, so you can see exactly how the shadow will look before copying the code.</p>" },
    ]},
    { heading: "How to Use Box Shadow Generator", content: [
      { type: "list", items: [
        "<p><strong>Step 1:</strong> Adjust the X offset slider to control the horizontal position of the shadow relative to the element — positive values move the shadow right, negative values move it left.</p>",
        "<p><strong>Step 2:</strong> Adjust the Y offset slider to control the vertical position — positive values move the shadow down, negative values move it up.</p>",
        "<p><strong>Step 3:</strong> Set the Blur radius slider to control shadow softness — a value of 0 creates a hard-edged shadow, while higher values produce increasingly diffused, soft edges.</p>",
        "<p><strong>Step 4:</strong> Set the Spread radius to expand or contract the shadow size relative to the element — positive values make the shadow larger, negative values shrink it smaller than the element.</p>",
        "<p><strong>Step 5:</strong> Pick a shadow color using the color picker input. The color is applied with full opacity by default.</p>",
        "<p><strong>Step 6:</strong> Toggle the inset checkbox to create an inner shadow that appears inside the element's border rather than outside.</p>",
        "<p><strong>Step 7:</strong> Copy the generated CSS declaration from the output panel and paste it into your stylesheet.</p>",
      ]},
    ]},
    { heading: "Why Use Box Shadow Generator", content: [
      { type: "paragraph", text: "<p>Box-shadow is one of the most frequently used CSS decorative properties for creating depth, elevation, and visual hierarchy in user interfaces. However, its four numeric parameters and color value make it tedious to get right by trial and error. The visual generator lets you iterate on shadow appearance in real time, seeing the effect immediately rather than guessing values, saving the file, and refreshing a browser tab. It is particularly useful for creating Material Design-style elevation levels, card hover effects, and focus ring indicators.</p>" },
    ]},
    { heading: "Privacy & Security", content: [
      { type: "paragraph", text: "This tool runs entirely in your browser — no data ever leaves your device. There is no server round-trip, no upload, no logging, and no account required. Your input is processed locally using client-side JavaScript and is never stored, transmitted, or accessible to anyone else. When you close the tab, everything disappears." },
    ]},
    { heading: "Frequently Asked Questions", content: [
      { type: "paragraph", text: "<h3>Can I stack multiple box shadows on one element?</h3><p>This tool generates a single box-shadow declaration. For stacked shadows with multiple layers, generate each shadow separately and combine them in your CSS by separating declarations with commas: box-shadow: shadow1, shadow2, shadow3;</p>" },
      { type: "paragraph", text: "<h3>Does the color picker support transparency?</h3><p>The native HTML color picker outputs hex values without alpha. To add transparency, copy the generated declaration and replace the hex color with an rgba() or hsla() value with your desired opacity.</p>" },
      { type: "paragraph", text: "<h3>What is the difference between blur and spread?</h3><p>Blur controls how soft or sharp the shadow edges are — higher values create more diffusion. Spread controls the shadow's size relative to the element — positive values expand it, negative values shrink it. A 0px blur with 5px spread creates a solid shadow exactly 5px larger than the element on all sides.</p>" },
      { type: "paragraph", text: "<h3>Is the preview accurate to real browser rendering?</h3><p>The preview uses the same CSS box-shadow property that browsers render natively, so what you see matches actual browser output. Minor sub-pixel rendering differences may occur between browser engines, but the visual effect is identical for practical purposes.</p>" },
    ]},
  ],
};
registerToolSeo("box-shadow-generator", box_shadow_generatorSeo);

const text_shadow_generatorSeo: ToolSeo = {
  sections: [
    { heading: "What is Text Shadow Generator", content: [
      { type: "paragraph", text: "<p>The Text Shadow Generator creates CSS text-shadow declarations through interactive controls for four properties: horizontal offset, vertical offset, blur radius, and shadow color. Unlike box-shadow, text-shadow does not have a spread parameter and cannot be set to inset. The tool renders a live preview showing the shadow applied to large sample text, and outputs the complete CSS property ready for use in stylesheets. Text-shadow is commonly used for improving text readability over background images, creating retro or neon effects, and adding subtle depth to headings.</p>" },
    ]},
    { heading: "How to Use Text Shadow Generator", content: [
      { type: "list", items: [
        "<p><strong>Step 1:</strong> Set the X offset value to control where the shadow falls horizontally relative to the text — positive values shift the shadow right, negative values shift it left.</p>",
        "<p><strong>Step 2:</strong> Set the Y offset value to control vertical shadow position — positive values place the shadow below the text, negative values place it above.</p>",
        "<p><strong>Step 3:</strong> Adjust the Blur radius — a value of 0 produces a sharp, hard-edged shadow, while higher values create increasingly soft, glow-like effects that are ideal for neon or ambient styles.</p>",
        "<p><strong>Step 4:</strong> Choose a shadow color using the color picker. For readability-enhancing shadows, use a darker shade of the text color. For neon effects, use a bright, saturated color.</p>",
        "<p><strong>Step 5:</strong> Copy the generated text-shadow CSS from the output panel and apply it to any text element in your stylesheet.</p>",
      ]},
    ]},
    { heading: "Why Use Text Shadow Generator", content: [
      { type: "paragraph", text: "<p>Text-shadow adds depth, readability, and visual hierarchy to headings, hero sections, and call-to-action text. When text sits over a busy background image or gradient, a subtle shadow dramatically improves legibility without requiring a solid background overlay. For creative applications, text-shadow enables effects ranging from subtle dimensional lift to dramatic glowing neon signs, all by combining multiple shadow layers with different offsets and colors.</p>" },
    ]},
    { heading: "Privacy & Security", content: [
      { type: "paragraph", text: "This tool runs entirely in your browser — no data ever leaves your device. There is no server round-trip, no upload, no logging, and no account required. Your input is processed locally using client-side JavaScript and is never stored, transmitted, or accessible to anyone else. When you close the tab, everything disappears." },
    ]},
    { heading: "Frequently Asked Questions", content: [
      { type: "paragraph", text: "<h3>Can I create layered text shadows for glow effects?</h3><p>Yes. Generate multiple shadows with different blur values and colors, then combine them in your CSS separated by commas. For a neon glow, use a large blur with a bright color behind a sharp dark shadow: text-shadow: 0 0 10px #ff00ff, 0 0 40px #ff00ff, 2px 2px 2px #000;</p>" },
      { type: "paragraph", text: "<h3>Does text-shadow affect text readability?</h3><p>Poorly chosen shadow colors or excessive blur can reduce readability. Generally, use a darker or lighter shade of the text color with a small offset for legibility-enhancing shadows. Avoid shadows that are wider than the text itself.</p>" },
      { type: "paragraph", text: "<h3>Does this work with web fonts and variable fonts?</h3><p>Yes. The text-shadow property applies to any rendered text regardless of font family, weight, or style. The preview uses a system font for display, but the generated CSS works identically with Google Fonts, local @font-face declarations, and variable fonts.</p>" },
      { type: "paragraph", text: "<h3>Can text-shadow be animated?</h3><p>Yes. You can transition or animate the text-shadow property to create effects like pulsing glows, moving light sources, or text that appears to emerge from shadow. Use CSS transitions for simple hover effects or @keyframes for continuous animations.</p>" },
    ]},
  ],
};
registerToolSeo("text-shadow-generator", text_shadow_generatorSeo);

